package io.baozhu.atlas.security;
import io.baozhu.atlas.api.SqlReviewResponse; import org.springframework.stereotype.Component; import java.util.*; import java.util.regex.Pattern;
@Component public class SqlSafetyGuard { private static final Pattern WRITE=Pattern.compile("\\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|merge|call)\\b",Pattern.CASE_INSENSITIVE);
 public SqlReviewResponse review(String sql,Set<String> allowedTables){String n=sql.trim().replaceAll("\\s+"," ");List<String> v=new ArrayList<>();String lower=n.toLowerCase();if(!lower.startsWith("select"))v.add("Only SELECT statements are allowed");if(WRITE.matcher(n).find())v.add("Write or DDL keyword detected");if(n.contains(";"))v.add("Multiple statements are not allowed");if(allowedTables.stream().map(String::toLowerCase).noneMatch(lower::contains))v.add("No allowed table referenced");if(lower.contains("information_schema")||lower.contains("pg_catalog"))v.add("System catalogs are not allowed");return new SqlReviewResponse(v.isEmpty(),v,n);}}
